19	/* UI对象 */
20	static lv_obj_t* display_base = NULL;
21	static lv_obj_t* brightness_container = NULL;
22	static lv_obj_t* brightness_indicator = NULL;
23	static lv_obj_t* timeout_base = NULL;
24	static lv_obj_t* timeout_roller = NULL;
25	
26	/* 亮度等级 */
27	static int current_level = 2; // 默认中等亮度
28	/* 抬腕亮屏状态 */
29	static bool wrist_raise_enabled = false;
30	/* 熄屏时间 (秒) */
31	static int screen_timeout = 10;
32	
