56	static void settings_display_create(void)
57	{
58	    settings_display_init_timeout();
59	    wrist_raise_load_config();
60	    wrist_raise_enabled = wrist_raise_get_enabled();
61	    // 获取当前亮度等级
62	    current_level = esp32s3_get_brightness();
63	    DISPLAY_LOG("settings get cur brightness level:%d", current_level);
64	    if (current_level < 0 || current_level > 4)
65	    {
66	        current_level = 2;  // 默认中等亮度
67	    }
68	    
69	    // 创建显示设置页面
70	    display_base = lv_obj_create(lv_scr_act());
71	    lv_obj_set_size(display_base, WATCH_SCREEN_WIDTH, WATCH_SCREEN_HEIGHT);
72	    lv_obj_clear_flag(display_base, LV_OBJ_FLAG_SCROLLABLE);
73	    lv_obj_set_style_bg_color(display_base, lv_color_hex(0x000000), LV_STATE_DEFAULT);
74	    lv_obj_set_style_border_width(display_base, 0, LV_STATE_DEFAULT);
75	    lv_obj_align(display_base, LV_ALIGN_CENTER, 0, 0);
76	
77	    // 创建标题
78	    lv_obj_t *title_label = lv_label_create(display_base);
79	    lv_label_set_text(title_label, "设置亮度");
80	    lv_obj_set_style_text_font(title_label, vw_resource_get_font(WATCH_REGULAR_FONT "_32"), 0);
81	    lv_obj_set_style_text_color(title_label, lv_color_white(), 0);
82	    lv_obj_align(title_label, LV_ALIGN_TOP_MID, 0, 26);
83	
84	    // 创建亮度调节容器 (横向)
85	    brightness_container = lv_obj_create(display_base);
86	    lv_obj_set_size(brightness_container, WATCH_BTN_WIDTH, 70);
87	    lv_obj_set_style_bg_color(brightness_container, lv_color_hex(0xFDFDFD), LV_STATE_DEFAULT);
88	    lv_obj_set_style_bg_opa(brightness_container, LV_OPA_20, LV_STATE_DEFAULT);
89	    lv_obj_set_style_border_width(brightness_container, 0, LV_STATE_DEFAULT);
90	    lv_obj_set_style_radius(brightness_container, 32, LV_STATE_DEFAULT);
91	    lv_obj_align(brightness_container, LV_ALIGN_TOP_MID, 0, 96);
92	    lv_obj_set_scrollbar_mode(brightness_container, LV_SCROLLBAR_MODE_OFF);
93	    lv_obj_set_scroll_dir(brightness_container, LV_DIR_NONE);
94	    lv_obj_set_style_pad_all(brightness_container, 0, 0);
95	    lv_obj_add_event_cb(brightness_container, brightness_bar_event_cb, LV_EVENT_ALL, NULL);
96	
97	    // 创建亮度指示器 (横向)
98	    brightness_indicator = lv_obj_create(brightness_container);
99	    lv_obj_set_width(brightness_indicator, WATCH_BTN_WIDTH * (current_level + 1) / 5);
100	    lv_obj_set_height(brightness_indicator, 70);
101	    lv_obj_set_style_bg_color(brightness_indicator, lv_color_hex(0x2BEA77), LV_STATE_DEFAULT);
102	    lv_obj_set_style_border_width(brightness_indicator, 0, LV_STATE_DEFAULT);
103	    lv_obj_set_style_radius(brightness_indicator, 32, LV_STATE_DEFAULT);
104	    lv_obj_align(brightness_indicator, LV_ALIGN_LEFT_MID, 0, 0);
105	    lv_obj_clear_flag(brightness_indicator, LV_OBJ_FLAG_CLICKABLE);
106	
107	    // 创建熄屏时间设置项
108	    static lv_style_t item_style;
109	    static bool style_initialized = false;
110	    if (!style_initialized) {
111	        lv_style_init(&item_style);
112	        lv_style_set_bg_opa(&item_style, LV_OPA_10);
113	        lv_style_set_bg_color(&item_style, lv_color_hex(0xFFFFFF));
114	        lv_style_set_border_width(&item_style, 0);
115	        lv_style_set_radius(&item_style, 32);
116	        lv_style_set_pad_all(&item_style, 0);
117	        lv_style_set_outline_width(&item_style, 0);
118	        lv_style_set_transform_width(&item_style, 0);
119	        lv_style_set_transform_height(&item_style, 0);
120	        lv_style_set_translate_x(&item_style, 0);
121	        lv_style_set_translate_y(&item_style, 0);
122	        style_initialized = true;
123	    }
124	
125	    static lv_style_t pressed_style;
126	    static bool pressed_style_initialized = false;
127	    if (!pressed_style_initialized) {
128	        lv_style_init(&pressed_style);
129	        lv_style_set_transform_width(&pressed_style, 0);
130	        lv_style_set_transform_height(&pressed_style, 0);
131	        lv_style_set_translate_x(&pressed_style, 0);
132	        lv_style_set_translate_y(&pressed_style, 0);
133	        lv_style_set_bg_opa(&pressed_style, LV_OPA_20);
134	        lv_style_set_bg_color(&pressed_style, lv_color_hex(0xFFFFFF));
135	        pressed_style_initialized = true;
136	    }
137	
138	    // 创建抬腕亮屏按钮
139	    lv_obj_t *wrist_raise_item = lv_obj_create(display_base);
140	    lv_obj_set_size(wrist_raise_item, WATCH_BTN_WIDTH, WATCH_BTN_HEIGHT);
141	    lv_obj_add_style(wrist_raise_item, &item_style, 0);
142	    lv_obj_add_style(wrist_raise_item, &pressed_style, LV_STATE_PRESSED);
143	    lv_obj_align(wrist_raise_item, LV_ALIGN_TOP_MID, 0, 190);
144	    lv_obj_clear_flag(wrist_raise_item, LV_OBJ_FLAG_SCROLLABLE);
145	    lv_obj_add_flag(wrist_raise_item, LV_OBJ_FLAG_EVENT_BUBBLE);
146	    
147	    // 抬腕亮屏文字
148	    lv_obj_t *wrist_raise_label = lv_label_create(wrist_raise_item);
149	    lv_label_set_text(wrist_raise_label, "抬腕亮屏");
150	    lv_obj_set_style_text_color(wrist_raise_label, lv_color_white(), 0);
151	    lv_obj_set_style_text_font(wrist_raise_label, vw_resource_get_font(WATCH_REGULAR_FONT "_32"), 0);
152	    lv_obj_set_pos(wrist_raise_label, 18, (WATCH_BTN_HEIGHT - 32) / 2);
153	    lv_obj_clear_flag(wrist_raise_label, LV_OBJ_FLAG_SCROLLABLE);
154	    
155	    // 创建抬腕亮屏开关
156	    lv_obj_t *wrist_switch = lv_switch_create(wrist_raise_item);
157	    lv_obj_set_size(wrist_switch, 57, 32);
158	    lv_obj_set_style_bg_color(wrist_switch, lv_color_hex(0x4D4D4D), LV_PART_MAIN | LV_STATE_DEFAULT);
159	    lv_obj_set_style_bg_color(wrist_switch, lv_color_hex(0x2BEA77), LV_PART_MAIN | LV_STATE_CHECKED);
160	    lv_obj_set_style_bg_color(wrist_switch, lv_color_hex(0x4D4D4D), LV_PART_INDICATOR | LV_STATE_DEFAULT);
161	    lv_obj_set_style_bg_color(wrist_switch, lv_color_hex(0x2BEA77), LV_PART_INDICATOR | LV_STATE_CHECKED);
162	    lv_obj_set_style_bg_color(wrist_switch, lv_color_hex(0xFFFFFF), LV_PART_KNOB | LV_STATE_DEFAULT);
163	    lv_obj_set_style_bg_color(wrist_switch, lv_color_hex(0xFFFFFF), LV_PART_KNOB | LV_STATE_CHECKED);
164	    lv_obj_add_event_cb(wrist_switch, wrist_raise_switch_event_cb, LV_EVENT_VALUE_CHANGED, NULL);
165	    if (wrist_raise_enabled) {
166	        lv_obj_add_state(wrist_switch, LV_STATE_CHECKED);
167	    }
168	    lv_obj_set_pos(wrist_switch, WATCH_BTN_WIDTH - 57 - 18, (WATCH_BTN_HEIGHT - 32) / 2);
169	    lv_obj_clear_flag(wrist_switch, LV_OBJ_FLAG_SCROLLABLE);
170	
171	    lv_obj_t *timeout_item = lv_obj_create(display_base);
172	    lv_obj_set_size(timeout_item, WATCH_BTN_WIDTH, WATCH_BTN_HEIGHT);
173	    lv_obj_add_style(timeout_item, &item_style, 0);
174	    lv_obj_add_style(timeout_item, &pressed_style, LV_STATE_PRESSED);
175	    lv_obj_align(timeout_item, LV_ALIGN_TOP_MID, 0, 314);
176	    lv_obj_clear_flag(timeout_item, LV_OBJ_FLAG_SCROLLABLE);
177	    lv_obj_add_flag(timeout_item, LV_OBJ_FLAG_EVENT_BUBBLE);
178	    lv_obj_add_event_cb(timeout_item, timeout_item_click_handler, LV_EVENT_CLICKED, NULL);
179	    
180	    // 熄屏时间文字
181	    lv_obj_t *timeout_label = lv_label_create(timeout_item);
182	    lv_label_set_text(timeout_label, "熄屏时间");
183	    lv_obj_set_style_text_color(timeout_label, lv_color_white(), 0);
184	    lv_obj_set_style_text_font(timeout_label, vw_resource_get_font(WATCH_REGULAR_FONT "_32"), 0);
185	    lv_obj_set_pos(timeout_label, 18, (WATCH_BTN_HEIGHT - 32) / 2);
186	    lv_obj_clear_flag(timeout_label, LV_OBJ_FLAG_SCROLLABLE);
187	    
188	    // 添加箭头图标
189	    lv_obj_t *timeout_arrow = lv_label_create(timeout_item);
190	    lv_label_set_text(timeout_arrow, ">");
191	    lv_obj_set_style_text_color(timeout_arrow, lv_color_white(), 0);
192	    lv_obj_set_style_text_font(timeout_arrow, vw_resource_get_font(WATCH_REGULAR_FONT "_32"), 0);
193	    lv_obj_align(timeout_arrow, LV_ALIGN_RIGHT_MID, -18, 0);
194	    lv_obj_clear_flag(timeout_arrow, LV_OBJ_FLAG_SCROLLABLE);
195	
196	    // 添加滑动手势处理
197	    lv_obj_add_event_cb(display_base, slide_gesture_handler, LV_EVENT_ALL, NULL);
198	
199	    // 将页面压入页面栈
200	    vw_watch_push_page(display_base);
201	}
