203	/**
204	 * 显示设置事件回调
205	 */
206	void settings_display_event_cb(lv_event_t *e)
207	{
208	    lv_event_code_t code = lv_event_get_code(e);
209	    
210	    if (code == LV_EVENT_CLICKED) {
211	        settings_display_create();
212	    }
213	}
