215	/**
216	 * 亮度调节条事件回调
217	 */
218	static void brightness_bar_event_cb(lv_event_t *e)
219	{
220	    lv_event_code_t code = lv_event_get_code(e);
221	    
222	    if (code == LV_EVENT_PRESSED || code == LV_EVENT_PRESSING) {
223	        // 获取触摸位置
224	        lv_point_t point;
225	        lv_indev_get_point(lv_indev_active(), &point);
226	        
227	        // 获取容器的位置和大小
228	        lv_area_t container_area;
229	        lv_obj_get_coords(brightness_container, &container_area);
230	        
231	        // 计算容器内的相对坐标
232	        lv_point_t container_point;
233	        container_point.x = point.x - container_area.x1;
234	        container_point.y = point.y - container_area.y1;
235	        
236	        // 限制在容器范围内
237	        if (container_point.x < 0) container_point.x = 0;
238	        int container_width = lv_obj_get_width(brightness_container);
239	        if (container_point.x > container_width) container_point.x = container_width;
240	        
241	        // 计算亮度等级 (0-4)
242	        int new_level = (container_point.x * 5) / container_width;
243	        if (new_level < 0) new_level = 0;
244	        if (new_level > 4) new_level = 4;
245	        
246	        // 更新亮度
247	        if (new_level != current_level) {
248	            current_level = new_level;
249	            lv_obj_set_width(brightness_indicator, container_width * (current_level + 1) / 5);
250	            lv_obj_align(brightness_indicator, LV_ALIGN_LEFT_MID, 0, 0);
251	            set_brightness(current_level);
252	        }
253	    }
254	}
255	
256	/**
257	 * 设置亮度
258	 */
259	static void set_brightness(int level)
260	{
261	    if (level >= 0 && level < 5) {
262	        esp32s3_set_brightness(level);
263	        DISPLAY_LOG("Set brightness to level %d", level);
264	    }
265	}
