270	static void wrist_raise_switch_event_cb(lv_event_t *e)
271	{
272	    lv_obj_t *obj = lv_event_get_target(e);
273	    wrist_raise_enabled = lv_obj_has_state(obj, LV_STATE_CHECKED);
274	    DISPLAY_LOG("Wrist raise enabled: %d", wrist_raise_enabled);
275	    wrist_raise_set_enabled(wrist_raise_enabled);
276	}
