286	/**
287	 * 创建熄屏时间设置页面
288	 */
289	static void settings_display_timeout_create(void)
290	{
291	    // 如果页面已存在，先销毁
292	    if (timeout_base != NULL) {
293	        lv_obj_del(timeout_base);
294	        timeout_base = NULL;
295	    }
296	
297	    // 创建熄屏时间设置页面
298	    timeout_base = lv_obj_create(lv_scr_act());
299	    lv_obj_set_size(timeout_base, WATCH_SCREEN_WIDTH, WATCH_SCREEN_HEIGHT);
300	    lv_obj_clear_flag(timeout_base, LV_OBJ_FLAG_SCROLLABLE);
301	    lv_obj_set_style_bg_color(timeout_base, lv_color_hex(0x000000), LV_STATE_DEFAULT);
302	    lv_obj_set_style_border_width(timeout_base, 0, LV_STATE_DEFAULT);
303	    lv_obj_align(timeout_base, LV_ALIGN_CENTER, 0, 0);
304	
305	    // 创建标题
306	    // lv_obj_t *title_label = lv_label_create(timeout_base);
307	    // lv_label_set_text(title_label, "熄屏时间");
308	    // lv_obj_set_style_text_font(title_label, vw_resource_get_font(WATCH_REGULAR_FONT "_32"), 0);
309	    // lv_obj_set_style_text_color(title_label, lv_color_white(), 0);
310	    // lv_obj_align(title_label, LV_ALIGN_TOP_MID, 0, 20);
311	
312	    // 创建滚轮 (5s, 10s, 20s, 30s, 1min, 5min)
313	
314	    timeout_roller = lv_roller_create(timeout_base);
315	    lv_roller_set_options(timeout_roller,
316	        "5秒\n10秒\n20秒\n30秒\n1分钟\n5分钟", LV_ROLLER_MODE_INFINITE);
317	
318	    // 计算当前选中的索引
319	    int selected_idx = 0;
320	    for (int i = 0; i < TIMEOUT_OPT_COUNT; i++) {
321	        if (screen_timeout <= timeout_values[i]) { selected_idx = i; break; }
322	    }
323	    if (screen_timeout > timeout_values[TIMEOUT_OPT_COUNT - 1])
324	        selected_idx = TIMEOUT_OPT_COUNT - 1;
325	    lv_roller_set_selected(timeout_roller, selected_idx, LV_ANIM_OFF);
326	    lv_obj_set_width(timeout_roller, WATCH_BTN_WIDTH);
327	    lv_obj_align(timeout_roller, LV_ALIGN_TOP_MID, 0, 20);
328	    
329	    // 设置滚轮样式
330	    lv_obj_set_style_border_color(timeout_roller, lv_color_hex(0x000000), LV_PART_MAIN | LV_STATE_DEFAULT);
331	    lv_obj_set_style_bg_color(timeout_roller, lv_color_hex(0xFFFFFF), LV_PART_SELECTED | LV_STATE_DEFAULT);
332	    lv_obj_set_style_bg_opa(timeout_roller, LV_OPA_10, LV_PART_SELECTED | LV_STATE_DEFAULT);
333	    lv_obj_set_style_text_color(timeout_roller, lv_color_hex(0xFFFFFF), LV_PART_SELECTED | LV_STATE_DEFAULT);
334	    lv_obj_set_style_bg_color(timeout_roller, lv_color_hex(0x000000), LV_PART_MAIN | LV_STATE_DEFAULT);
335	    lv_obj_set_style_text_color(timeout_roller, lv_color_hex(0x696969), LV_PART_MAIN | LV_STATE_DEFAULT);
336	    lv_obj_set_style_text_align(timeout_roller, LV_TEXT_ALIGN_CENTER, 0);
337	    const lv_font_t *timeout_roller_font = vw_resource_get_font(WATCH_REGULAR_FONT "_36");
338	    lv_obj_set_style_text_font(timeout_roller, timeout_roller_font, 0);
339	    lv_obj_set_style_radius(timeout_roller, 32, LV_PART_SELECTED | LV_STATE_DEFAULT);
340	    lv_roller_set_visible_row_count(timeout_roller, 3);
341	    int32_t timeout_line_h = lv_font_get_line_height(timeout_roller_font);
342	    lv_obj_set_style_text_line_space(timeout_roller, WATCH_BTN_HEIGHT - timeout_line_h, LV_PART_MAIN);
343	    lv_obj_set_height(timeout_roller, WATCH_BTN_HEIGHT * 3);
344	    lv_obj_clear_flag(timeout_roller, LV_OBJ_FLAG_GESTURE_BUBBLE);
345	    lv_obj_add_flag(timeout_roller, LV_OBJ_FLAG_EVENT_BUBBLE);
346	
347	    // 创建确认按钮
348	    lv_obj_t *confirm_btn = lv_btn_create(timeout_base);
349	    lv_obj_add_event_cb(confirm_btn, timeout_roller_confirm_handler, LV_EVENT_CLICKED, NULL);
350	    lv_obj_set_size(confirm_btn, 150, 100);
351	    lv_obj_set_style_bg_color(confirm_btn, lv_color_hex(0x2D47CB), LV_STATE_DEFAULT);
352	    lv_obj_set_style_border_width(confirm_btn, 0, LV_STATE_DEFAULT);
353	    lv_obj_set_style_radius(confirm_btn, 32, LV_STATE_DEFAULT);
354	    lv_obj_set_style_shadow_width(confirm_btn, 0, LV_PART_MAIN | LV_STATE_DEFAULT);
355	    lv_obj_align(confirm_btn, LV_ALIGN_TOP_LEFT, 25, 335);
356	    lv_obj_t *confirm_btn_label = lv_label_create(confirm_btn);
357	    lv_label_set_text(confirm_btn_label, "确认");
358	    lv_obj_set_style_text_font(confirm_btn_label, vw_resource_get_font(WATCH_REGULAR_FONT "_32"), 0);
359	    lv_obj_set_style_text_color(confirm_btn_label, lv_color_white(), 0);
360	    lv_obj_center(confirm_btn_label);
361	
362	    // 创建取消按钮
363	    lv_obj_t *cancel_btn = lv_btn_create(timeout_base);
364	    lv_obj_add_event_cb(cancel_btn, timeout_roller_cancel_handler, LV_EVENT_CLICKED, NULL);
365	    lv_obj_set_size(cancel_btn, 150, 100);
366	    lv_obj_set_style_bg_color(cancel_btn, lv_color_hex(0xFFFFFF), LV_STATE_DEFAULT);
367	    lv_obj_set_style_bg_opa(cancel_btn, LV_OPA_10, LV_STATE_DEFAULT);
368	    lv_obj_set_style_border_width(cancel_btn, 0, LV_STATE_DEFAULT);
369	    lv_obj_set_style_radius(cancel_btn, 32, LV_STATE_DEFAULT);
370	    lv_obj_set_style_shadow_width(cancel_btn, 0, LV_PART_MAIN | LV_STATE_DEFAULT);
371	    lv_obj_align(cancel_btn, LV_ALIGN_TOP_LEFT, 200, 335);
372	    lv_obj_t *cancel_btn_label = lv_label_create(cancel_btn);
373	    lv_label_set_text(cancel_btn_label, "取消");
374	    lv_obj_set_style_text_font(cancel_btn_label, vw_resource_get_font(WATCH_REGULAR_FONT "_32"), 0);
375	    lv_obj_set_style_text_color(cancel_btn_label, lv_color_white(), 0);
376	    lv_obj_center(cancel_btn_label);
377	
378	    // 添加滑动手势处理
379	    lv_obj_add_event_cb(timeout_base, slide_gesture_setting_display_timeout_handler, LV_EVENT_ALL, NULL);
380	
381	    // 将页面压入页面栈
382	    vw_watch_push_page(timeout_base);
383	}
