385	/**
386	 * 熄屏时间确认按钮事件回调
387	 */
388	static void timeout_roller_confirm_handler(lv_event_t *e)
389	{
390	    uint16_t selected = lv_roller_get_selected(timeout_roller);
391	    selected %= TIMEOUT_OPT_COUNT;
392	    screen_timeout = timeout_values[selected];
393	    display_set_timeout(screen_timeout);
394	    DISPLAY_LOG("Set screen timeout to %d seconds", screen_timeout);
395	    
396	    // 退出页面
397	    if (timeout_base != NULL) {
398	        vw_watch_pop_page(timeout_base);
399	        lv_obj_del(timeout_base);
400	        timeout_base = NULL;
401	    }
402	}
403	
404	static void timeout_roller_cancel_handler(lv_event_t *e)
405	{
406	    DISPLAY_LOG("Set screen cancel.");
407	    // 退出页面
408	    if (timeout_base != NULL) {
409	        vw_watch_pop_page(timeout_base);
