75	static uint64_t sensor_get_time_ms(void)
76	{
77	    struct timespec ts;
78	    clock_gettime(CLOCK_MONOTONIC, &ts);
79	    return (uint64_t)ts.tv_sec * 1000 + (uint64_t)ts.tv_nsec / 1000000;
80	}
