82	int sensor_data_init(void)
83	{
84	    if (g_sensor_initialized) {
85	        return 0;
86	    }
87	
88	    FAR const struct orb_metadata *meta;
89	
90	    meta = ORB_ID(sensor_accel);
91	    g_fd_accel = orb_subscribe_multi(meta, 0);
92	    if (g_fd_accel < 0) {
93	        SENSOR_LOG("Failed to subscribe sensor_accel: %d", g_fd_accel);
94	        return -1;
95	    }
96	    orb_set_interval(g_fd_accel, SENSOR_SAMPLE_INTERVAL);
97	
98	    meta = ORB_ID(sensor_gyro);
99	    g_fd_gyro = orb_subscribe_multi(meta, 0);
100	    if (g_fd_gyro < 0) {
101	        SENSOR_LOG("Failed to subscribe sensor_gyro: %d", g_fd_gyro);
102	        orb_unsubscribe(g_fd_accel);
103	        g_fd_accel = -1;
104	        return -1;
105	    }
106	    orb_set_interval(g_fd_gyro, SENSOR_SAMPLE_INTERVAL);
107	
108	    g_sensor_initialized = true;
109	    g_last_az = -1.0f;
110	    SENSOR_LOG("Sensor data module initialized");
111	    return 0;
112	}
113	
114	void sensor_data_deinit(void)
115	{
116	    if (g_fd_accel >= 0) {
117	        orb_unsubscribe(g_fd_accel);
118	        g_fd_accel = -1;
119	    }
120	    if (g_fd_gyro >= 0) {
121	        orb_unsubscribe(g_fd_gyro);
122	        g_fd_gyro = -1;
123	    }
124	    g_sensor_initialized = false;
125	}
