127	int sensor_data_read(sensor_imu_data_t *data)
128	{
129	    if (!g_sensor_initialized || !data) {
130	        return -1;
131	    }
132	
133	    struct pollfd fds[2];
134	    fds[0].fd = g_fd_accel;
135	    fds[0].events = POLLIN;
136	    fds[1].fd = g_fd_gyro;
137	    fds[1].events = POLLIN;
138	
139	    int ret = poll(fds, 2, SENSOR_POLL_TIMEOUT);
140	    if (ret <= 0) {
141	        return -1;
142	    }
143	
144	    FAR const struct orb_metadata *meta;
145	
146	    if (fds[0].revents & POLLIN) {
147	        struct sensor_accel accel_data;
148	        meta = ORB_ID(sensor_accel);
149	        if (orb_copy(meta, g_fd_accel, &accel_data) == 0) {
150	            data->accel.x = accel_data.x;
151	            data->accel.y = accel_data.y;
152	            data->accel.z = accel_data.z;
153	            data->temperature = accel_data.temperature;
154	            data->timestamp = accel_data.timestamp;
155	        }
156	    }
157	
158	    if (fds[1].revents & POLLIN) {
159	        struct sensor_gyro gyro_data;
160	        meta = ORB_ID(sensor_gyro);
161	        if (orb_copy(meta, g_fd_gyro, &gyro_data) == 0) {
162	            data->gyro.x = gyro_data.x;
163	            data->gyro.y = gyro_data.y;
164	            data->gyro.z = gyro_data.z;
165	            if (data->timestamp == 0) {
166	                data->timestamp = gyro_data.timestamp;
167	            }
168	        }
169	    }
170	
171	    return 0;
172	}
