174	/**
175	 * 统一传感器监控定时器
176	 * 一次读传感器, 同时判断抬腕亮屏(az正→负)和摔倒(gyro>300)
177	 */
178	static void sensor_monitor_timer_cb(lv_timer_t *timer)
179	{
180	    sensor_imu_data_t data;
181	    if (sensor_data_read(&data) != 0) {
182	        return;
183	    }
184	
185	    float gyro_mag = sqrtf(data.gyro.x * data.gyro.x +
186	                           data.gyro.y * data.gyro.y +
187	                           data.gyro.z * data.gyro.z);
188	
189	    float az_now = data.accel.z;
190	    float az_prev = g_last_az;
191	    g_last_az = az_now;
192	
193	    float accel_mag = sqrtf(data.accel.x * data.accel.x +
194	                            data.accel.y * data.accel.y +
195	                            data.accel.z * data.accel.z);
196	    (void)accel_mag;
197	
198	    uint64_t now = sensor_get_time_ms();
199	
200	    bool z_up   = (az_prev > 0.3f  && az_now < -0.3f);
201	    bool has_rot = (gyro_mag > GYRO_ROTATION_THRESH);
202	    bool gyro_high = (gyro_mag > FALL_GYRO_THRESH);
203	    float az_change = fabsf(az_now - az_prev);
204	
205	    if (az_change > FALL_AZ_CHANGE_THRESH && g_step_paused) {
206	        g_fall_z_up_time = now;
207	    }
208	
209	    bool in_fall_window = (g_fall_z_up_time > 0 && now - g_fall_z_up_time <= FALL_WINDOW_MS);
210	    bool fall_cond = (in_fall_window && gyro_high && g_step_paused);
211	
212	    if (!g_step_paused) {
213	        sensor_step_counter_update(&data);
214	    }
215	
216	    // printf("[SM] az=%.2f->%.2f z_up=%d a=%.2f g=%.2f rot=%d fall=%d fw=%d\n",
217	    //        az_prev, az_now, z_up, accel_mag,
218	    //        gyro_mag, has_rot, fall_cond, in_fall_window);
219	
220	    if (z_up && has_rot && g_wrist_raise_enabled && getchange() == 2) {
221	        if (now - g_wrist_raise_last_trigger > WRIST_RAISE_COOLDOWN_MS) {
222	            g_wrist_raise_last_trigger = now;
223	            g_fall_last_trigger = now;
224	            esp32s3_display_on();
225	            setchange(1);
226	            ft3168_display_timeout_setup();
227	            SENSOR_LOG("[WRIST] Screen on");
228	        }
229	    }
230	
231	    if (fall_cond) {
232	        if (now - g_fall_last_trigger > FALL_COOLDOWN_MS) {
233	            g_fall_last_trigger = now;
234	            g_wrist_raise_last_trigger = now;
235	            g_fall_z_up_time = 0;
236	        }
237	    }
238	}
