240	bool sensor_detect_wrist_raise(void)
241	{
242	    sensor_imu_data_t data;
243	    if (sensor_data_read(&data) != 0) {
244	        return false;
245	    }
246	
247	    float gyro_mag = sqrtf(data.gyro.x * data.gyro.x +
248	                           data.gyro.y * data.gyro.y +
249	                           data.gyro.z * data.gyro.z);
250	
251	    float az_now = data.accel.z;
252	    float az_prev = g_last_az;
253	    g_last_az = az_now;
254	
255	    bool z_up = (az_prev > 0.3f && az_now < -0.3f);
256	    bool has_rotation = (gyro_mag > GYRO_ROTATION_THRESH);
257	
258	    if (z_up && has_rotation) {
259	        uint64_t now = sensor_get_time_ms();
260	        if (now - g_wrist_raise_last_trigger > WRIST_RAISE_COOLDOWN_MS) {
261	            g_wrist_raise_last_trigger = now;
262	            return true;
263	        }
264	    }
265	
266	    return false;
