327	
328	void sensor_step_counter_update(const sensor_imu_data_t *data)
329	{
330	    if (!data || g_step_paused) {
331	        return;
332	    }
333	
334	    float accel_mag = sqrtf(data->accel.x * data->accel.x +
335	                            data->accel.y * data->accel.y +
336	                            data->accel.z * data->accel.z);
337	
338	    uint64_t now = sensor_get_time_ms();
339	
340	    float adaptive_threshold = STEP_DETECT_THRESHOLD;
341	    if (accel_mag > GRAVITY_1G) {
342	        adaptive_threshold = 0.2f;
343	    } else if (accel_mag > 3.0f) {
344	        adaptive_threshold = 0.15f;
345	    } else if (accel_mag > 1.5f) {
346	        adaptive_threshold = 0.1f;
347	    } else {
348	        adaptive_threshold = 0.05f;
349	    }
350	
351	    bool significant_change = fabsf(accel_mag - g_step_last_accel_mag) > 0.02f;
352	
353	    if (accel_mag > g_step_last_accel_mag) {
354	        if (!g_step_rising) {
355	            g_step_rising = true;
356	            g_step_dir_change_samples = 0;
357	            float swing = g_step_accel_max - g_step_accel_min;
358	            if (swing > adaptive_threshold || (swing > 0.05f && significant_change)) {
359	                uint64_t step_interval = now - g_step_last_peak_time;
360	                if (g_step_last_peak_time != 0 && step_interval > STEP_MAX_INTERVAL_MS) {
361	                    g_step_last_peak_time = 0;
362	                    step_interval = 0;
363	                }
364	                if (g_step_last_peak_time == 0 ||
365	                    (step_interval >= STEP_MIN_INTERVAL_MS &&
366	                     step_interval <= STEP_MAX_INTERVAL_MS)) {
367	                    g_step_count++;
368	                    float adaptive_step_length = g_step_length;
369	                    if (accel_mag > 4.5f) {
370	                        adaptive_step_length = g_step_length * 1.2f;
371	                    } else if (accel_mag < 2.0f) {
372	                        adaptive_step_length = g_step_length * 0.8f;
373	                    }
374	                    g_step_distance += adaptive_step_length;
375	                    g_step_last_peak_time = now;
376	                    SENSOR_LOG("[STEP] #%d dist=%.2f swing=%.2f mag=%.2f thresh=%.2f",
377	                           g_step_count, g_step_distance, swing, accel_mag, adaptive_threshold);
378	                }
379	            }
380	            g_step_accel_max = accel_mag;
381	            g_step_accel_min = accel_mag;
382	        }
383	        g_step_dir_change_samples++;
