1	/**
2	 * @file display_control.c
3	 * 定时息屏控制实现。
4	 *
5	 * 通过 LVGL 定时器监控显示不活动时间，超时后调用 esp32s3_display_off()
6	 * 关闭屏幕；检测到触摸活动后调用 esp32s3_display_on() 重新点亮。
7	 */
8	
9	#include <stdio.h>
10	#include <string.h>
11	#include <unistd.h>
12	#include <fcntl.h>
13	#include <syslog.h>
14	#include <nuttx/lcd/co5300.h>
15	#include <lvgl/lvgl.h>
16	
17	#define TIMEOUT_FILE    "/mnt/spif/display_timeout"
18	#define DEFAULT_TIMEOUT  10
19	#define TIMER_PERIOD_MS  500
20	
21	static int       g_timeout_sec  = DEFAULT_TIMEOUT;
22	static int       g_change       = 0;    /* 0=正常, 1=亮屏中, 2=需亮屏 */
23	static bool      g_screen_off   = false;
24	static lv_timer_t *g_timer      = NULL;
25	/* 自动熄屏开关：语音交互场景（表情潮玩模式、小通AI页面）调用
26	 * display_timeout_disable() 挂起熄屏，退出时 display_timeout_enable()
27	 * 恢复。禁用期间定时器保持运行但不执行熄屏。 */
28	static bool      g_timeout_disabled = false;
29	
30	static void timeout_timer_cb(lv_timer_t *timer)
31	{
32	    lv_disp_t *disp = lv_disp_get_default();
33	    if (!disp) return;
34	
35	    if (g_timeout_disabled) return;
36	
37	    uint32_t inactive_ms = lv_disp_get_inactive_time(disp);
38	
39	    if (g_screen_off) {
40	        if (inactive_ms < 300) {
41	            esp32s3_display_on();
42	            g_screen_off = false;
43	            g_change = 0;
44	            syslog(LOG_INFO, "[DISPLAY] touch detected, screen on\n");
45	        }
46	    } else {
47	        uint32_t threshold = (uint32_t)g_timeout_sec * 1000;
48	        if (inactive_ms >= threshold) {
49	            esp32s3_display_off();
50	            g_screen_off = true;
51	            g_change = 2;
52	            syslog(LOG_INFO, "[DISPLAY] timeout %ds, screen off\n",
53	                   g_timeout_sec);
54	        }
55	    }
56	}
57	
58	void display_set_timeout(int timeout)
59	{
60	    if (timeout < 5 || timeout > 300) timeout = DEFAULT_TIMEOUT;
61	    g_timeout_sec = timeout;
62	
63	    int fd = open(TIMEOUT_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644);
64	    if (fd >= 0) {
65	        char buf[16];
66	        int len = snprintf(buf, sizeof(buf), "%d\n", timeout);
67	        write(fd, buf, len);
68	        close(fd);
69	    }
70	
71	    if (!g_timer) {
72	        g_timer = lv_timer_create(timeout_timer_cb, TIMER_PERIOD_MS, NULL);
73	    }
74	    syslog(LOG_INFO, "[DISPLAY] set timeout = %d s\n", timeout);
75	}
76	
77	int display_get_timeout(void)
78	{
79	    int fd = open(TIMEOUT_FILE, O_RDONLY);
80	    if (fd >= 0) {
81	        char buf[16] = {0};
82	        read(fd, buf, sizeof(buf) - 1);
83	        close(fd);
84	        int t = atoi(buf);
85	        if (t >= 5 && t <= 300) g_timeout_sec = t;
86	    }
87	    return g_timeout_sec;
88	}
89	
90	void ft3168_display_timeout_setup(void)
91	{
92	    if (!g_timer) {
93	        g_timer = lv_timer_create(timeout_timer_cb, TIMER_PERIOD_MS, NULL);
94	    }
95	    if (g_screen_off) {
96	        esp32s3_display_on();
97	        g_screen_off = false;
98	        g_change = 0;
99	    }
100	}
101	
102	void setNull_display_timeout_timer(void)
103	{
104	    if (g_timer) {
105	        lv_timer_del(g_timer);
106	        g_timer = NULL;
107	    }
108	}
109	
110	/**
111	 * @brief 暂停自动熄屏（语音交互场景：表情潮玩模式、小通AI页面）。
112	 *
113	 * 只挂起熄屏判定，定时器不删除；若屏幕已熄则立即点亮。
114	 * 与语音侧 180s 空闲待机（表情隐藏）相互独立，互不影响。
115	 */
116	void display_timeout_disable(void)
117	{
118	    if (!g_timeout_disabled) {
119	        g_timeout_disabled = true;
120	        if (g_screen_off) {
121	            esp32s3_display_on();
122	            g_screen_off = false;
123	            g_change = 0;
124	        }
125	        syslog(LOG_INFO, "[DISPLAY] auto off disabled\n");
126	    }
127	}
128	
129	/**
130	 * @brief 恢复自动熄屏，并从当前时刻重新计时（避免退出语音场景后
131	 * 按上一次触摸时间立即熄屏）。
132	 */
133	void display_timeout_enable(void)
134	{
135	    if (!g_timeout_disabled) return;
136	    g_timeout_disabled = false;
137	
138	    lv_disp_t *disp = lv_disp_get_default();
139	    if (disp) lv_display_trigger_activity(disp);
140	
141	    syslog(LOG_INFO, "[DISPLAY] auto off enabled\n");
142	}
143	
144	int getchange(void)
145	{
146	    return g_change;
147	}
148	
149	void setchange(int v)
150	{
151	    g_change = v;
152	}

