94	static void goto_next_state(void)
95	{
96	  switch (current_state)
97	    {
98	      case STATE_INIT:
99	        /* 切换到显示logo状态 */
100	        current_state = STATE_SHOW_LOGO;
101	        if (current_obj != NULL)
102	          {
103	            lv_obj_del(current_obj);
104	          }
105	        current_obj = boot_logo_init(content_area);
106	        lv_task_handler();
107	        
108	        lv_timer_t *timer1 = lv_timer_create(state_timer_cb, LOGO_DISPLAY_TIME, NULL);
109	        lv_timer_set_repeat_count(timer1, 1);
110	        break;
111	
112	      case STATE_SHOW_LOGO:
113	        /* 切换到显示动画状态 */
114	        current_state = STATE_SHOW_ANIM;
115	
116	        /* 销毁logo并显示动画 */
117	        boot_logo_deinit(current_obj);
118	        LAUNCHER_LOG("boot_animation init, start load power anim: %p", current_obj);
119	        current_obj = boot_animation_init(content_area);
120	        lv_task_handler();
121	        
122	        /* 设置动画显示时间 */
123	        lv_timer_t *timer2 = lv_timer_create(state_timer_cb, ANIMATION_DISPLAY_TIME, NULL);
124	        lv_timer_set_repeat_count(timer2, 1);
125	        break;
126	
127	      case STATE_SHOW_ANIM:
128	        /* 切换到显示时钟状态 */
129	        current_state = STATE_SHOW_CLOCK;
130	        LAUNCHER_LOG("destory power anim, start dial init");
