211	
212	  /* 1. 停止业务定时器 */
213	  if (charging_timer != NULL)
214	    {
215	      lv_timer_del(charging_timer);
216	      charging_timer = NULL;
217	    }
218	
219	  /* 2. 停止闹钟服务与传感器监控 */
220	  alarm_service_deinit();
221	  sensor_wrist_raise_timer_stop();
222	  sensor_data_deinit();
