224	  /* 3. 删除页面栈中所有页面（反向删除，与 lv_watch_back_go_home 一致） */
225	  for (int i = page_stack_size - 1; i >= 0; i--)
226	    {
227	      if (page_stack[i] != NULL)
228	        {
229	          lv_obj_del_async(page_stack[i]);
230	          page_stack[i] = NULL;
231	        }
232	    }
233	  page_stack_size = 0;
234	
235	  /* 4. 删除表盘（含 g_clock_timer） */
236	  if (dial_get_container() != NULL)
