557	/* Global brightness level, used by setpower for wake-up restore */
558	extern uint8_t brightness;
559	
560	static int co5300_setpower(FAR struct lcd_dev_s *dev, int power)
561	{
562	  FAR struct esp32s3_co5300_dev_s *priv =
563	    (FAR struct esp32s3_co5300_dev_s *)dev;
564	
565	  DEBUGASSERT(dev);
566	
567	  if (power > 0)
568	    {
569	      /* Wake-up sequence: if display was off, we need to send Sleep Out
570	       * first to ensure the panel exits low-power state, then wait the
571	       * required delay before turning the display on.
572	       */
573	
574	      if (priv->power == 0)
575	        {
576	          /* Send Sleep Out (0x11) to wake panel from low-power state */
577	          lcd_write_cmd(priv->qspi, 0x11, NULL, 0);
578	
579	          /* CO5300 datasheet requires 120ms delay after Sleep Out */
580	          up_mdelay(120);
581	
582	          /* Re-send brightness level after wake-up, otherwise panel
583	           * may show at wrong brightness or appear blank.
584	           */
585	          lcd_write_cmd(priv->qspi, 0x51,
586	                        (uint8_t[]){brightness > 0 ? brightness : 0xFF}, 1);
587	          up_mdelay(10);
588	        }
589	
590	      /* Display On (0x29) */
591	      lcd_write_cmd(priv->qspi, 0x29, NULL, 0);
592	      up_mdelay(10);
593	      priv->power = 1;
594	    }
595	  else
596	    {
597	      /* Turn off display and enter sleep for lower power consumption.
598	       * Sequence: Display Off (0x28) -> Sleep In (0x10).
599	       * Sleep In puts the panel into low-power state.
600	       */
601	      lcd_write_cmd(priv->qspi, 0x28, NULL, 0);
602	      up_mdelay(10);
603	      lcd_write_cmd(priv->qspi, 0x10, NULL, 0);
604	      priv->power = 0;
605	    }
606	
607	  return OK;
608	}
