63	static int flush_data(FAR struct ymodem_priv_s *priv)
64	{
65	  while (priv->fd > 0 && circbuf_used(&priv->circ))
66	    {
67	      FAR const uint8_t *buffer;
68	      size_t i = 0;
69	      size_t size;
70	
71	      buffer = circbuf_get_readptr(&priv->circ, &size);
72	      while (i < size)
73	        {
74	          ssize_t ret = write(priv->fd, buffer + i, size - i);
75	          if (ret < 0)
76	            {
77	              return -errno;
78	            }
79	
80	          i += ret;
81	        }
82	
83	      circbuf_readcommit(&priv->circ, size);
84	    }
85	
86	  return 0;
87	}
