94	  while (priv->exited == false)
95	    {
96	      if (circbuf_used(&priv->circ) <= priv->threshold)
97	        {
98	          pthread_cond_wait(&priv->cond, &priv->mutex);
99	          continue;
100	        }
101	
102	      if (flush_data(priv) < 0)
103	        {
104	          pthread_mutex_unlock(&priv->mutex);
105	          return NULL;
106	        }
107	    }
108	
109	  flush_data(priv);
110	  pthread_mutex_unlock(&priv->mutex);
111	  return NULL;
112	}
113	
114	static int write_data(FAR struct ymodem_priv_s *priv,
115	                      FAR const uint8_t *data, size_t size)
116	{
117	  size_t i = 0;
118	
119	  if (priv->buffersize)
120	    {
121	      pthread_mutex_lock(&priv->mutex);
122	      while (i < size)
123	        {
124	          ssize_t ret = circbuf_write(&priv->circ, data + i, size - i);
125	          if (ret < 0)
126	            {
127	              pthread_mutex_unlock(&priv->mutex);
128	              return ret;
129	            }
130	          else if (ret == 0)
131	            {
132	              ret = flush_data(priv);
133	              if (ret < 0)
134	                {
135	                  pthread_mutex_unlock(&priv->mutex);
136	                  return ret;
137	                }
138	            }
139	          else
140	            {
141	              i += ret;
142	            }
143	        }
144	
145	      if (circbuf_used(&priv->circ) > priv->threshold)
146	        {
147	          pthread_cond_signal(&priv->cond);
148	        }
149	
150	      pthread_mutex_unlock(&priv->mutex);
151	    }
152	  else
153	    {
154	      while (i < size)
155	        {
156	          ssize_t ret = write(priv->fd, data + i, size - i);
157	          if (ret < 0)
158	            {
159	              return -errno;
160	            }
161	
162	          i += ret;
163	        }
164	    }
165	
166	  return 0;
167	}
