169	static int handler(FAR struct ymodem_ctx_s *ctx)
170	{
171	  FAR struct ymodem_priv_s *priv = ctx->priv;
172	  int ret;
173	
174	  if (ctx->packet_type == YMODEM_FILENAME_PACKET)
175	    {
176	      char filename[PATH_MAX + 1];
177	      FAR char *temp;
178	
179	      if (priv->fd > 0)
180	        {
181	          if (priv->buffersize)
182	            {
183	              pthread_mutex_lock(&priv->mutex);
184	              ret = flush_data(priv);
185	              pthread_mutex_unlock(&priv->mutex);
186	              if (ret < 0)
187	                {
188	                  return ret;
189	                }
190	            }
191	
192	          close(priv->fd);
193	        }
194	
195	      temp = ctx->file_name;
196	
197	      if (priv->skip_prefix != NULL)
198	        {
199	          size_t len = strlen(priv->skip_prefix);
200	
201	          if (strncmp(ctx->file_name, priv->skip_prefix,
202	                      len) == 0)
203	            {
204	              temp += len;
205	            }
206	        }
207	
208	      if (priv->skip_suffix != NULL)
209	        {
210	          size_t len = strlen(temp);
211	          size_t len2 = strlen(priv->skip_suffix);
212	
213	          if (len > len2 && strcmp(temp + len - len2,
214	                                   priv->skip_suffix) == 0)
215	            {
216	              temp[len - len2] = '\0';
217	            }
218	        }
219	
220	      if (priv->foldname != NULL)
221	        {
222	          ret = snprintf(filename, sizeof(filename), "%s/%s%s%s",
223	                         priv->foldname, priv->prepend_prefix, temp,
224	                         priv->append_suffix);
225	        }
226	      else
227	        {
228	          ret = snprintf(filename, sizeof(filename), "%s%s%s",
229	                         priv->prepend_prefix, temp, priv->append_suffix);
230	        }
231	
232	      if (ret < 0)
233	        {
234	          return ret;
235	        }
236	
237	      else if (ret >= sizeof(filename))
238	        {
239	          return -ENAMETOOLONG;
240	        }
241	
242	      priv->fd = open(filename, O_CREAT | O_WRONLY, 0777);
243	      if (priv->fd < 0)
244	        {
245	          return -errno;
246	        }
247	
248	      priv->file_saved_size = 0;
249	    }
250	  else if (ctx->packet_type == YMODEM_DATA_PACKET)
251	    {
252	      size_t size;
253	
254	      if (priv->file_saved_size + ctx->packet_size > ctx->file_length)
255	        {
256	          size = ctx->file_length - priv->file_saved_size;
257	        }
258	      else
259	        {
260	          size = ctx->packet_size;
261	        }
262	
263	      ret = write_data(priv, ctx->data, size);
264	      if (ret < 0)
265	        {
266	          return ret;
267	        }
268	
269	      priv->file_saved_size += size;
270	    }
271	
272	  return 0;
273	}
