275	static int async_init(FAR struct ymodem_priv_s *priv)
276	{
277	  int ret;
278	
279	  ret = circbuf_init(&priv->circ, NULL, priv->buffersize);
280	  if (ret < 0)
281	    {
282	      fprintf(stderr, "ERROR: circbuf_init error\n");
283	      return ret;
284	    }
285	
286	  ret = pthread_mutex_init(&priv->mutex, NULL);
287	  if (ret > 0)
288	    {
289	      fprintf(stderr, "ERROR: pthread_mutex_init error\n");
290	      ret = -ret;
291	      goto circ_err;
292	    }
293	
294	  ret = pthread_cond_init(&priv->cond, NULL);
295	  if (ret > 0)
296	    {
297	      fprintf(stderr, "ERROR: pthread_cond_init error\n");
298	      ret = -ret;
299	      goto mutex_err;
300	    }
301	
302	  ret = pthread_create(&priv->pid, NULL, async_write, priv);
303	  if (ret > 0)
304	    {
305	      ret = -ret;
306	      goto cond_err;
307	    }
308	
309	  return ret;
310	cond_err:
311	  pthread_cond_destroy(&priv->cond);
312	mutex_err:
313	  pthread_mutex_destroy(&priv->mutex);
314	circ_err:
315	  circbuf_uninit(&priv->circ);
316	  return ret;
317	}
318	
319	static void async_uninit(FAR struct ymodem_priv_s *priv)
320	{
321	  pthread_mutex_lock(&priv->mutex);
322	  priv->exited = true;
323	  pthread_cond_signal(&priv->cond);
324	  pthread_mutex_unlock(&priv->mutex);
325	  pthread_join(priv->pid, NULL);
326	  pthread_cond_destroy(&priv->cond);
327	  pthread_mutex_destroy(&priv->mutex);
328	  circbuf_uninit(&priv->circ);
329	}
