339	  fprintf(stderr,
340	          "\t-f <foldname>: Save remote file fold. Default: Current fold\n");
341	  fprintf(stderr,
342	          "\t-p|--skip_prefix <prefix>: Remove file name prefix\n");
343	  fprintf(stderr,
344	          "\t-s|--skip_suffix <suffix>: Remove file name suffix\n");
345	  fprintf(stderr,
346	          "\t-e|--prepend_prefix <prefix>: prepend file name a prefix\n");
347	  fprintf(stderr,
348	          "\t-a|--append_suffix <suffix>: append file name a suffix\n");
349	  fprintf(stderr,
350	          "\t-b|--buffersize <size>: Asynchronously receive buffer size."
351	          "If greater than 0, accept data asynchronously, Default: 0kB\n");
352	  fprintf(stderr,
353	          "\t-t|--threshold <size>: Threshold for writing asynchronously."
354	          "Threshold must be less than or equal buffersize, Default: 0kB\n");
355	  fprintf(stderr,
356	          "\t-i|--interval <time>: Waiting interval for transmitting data."
357	          "Max:255 Min:1 Default:15 unit: 100 milliseconds\n");
