371	int main(int argc, FAR char *argv[])
372	{
373	  struct ymodem_priv_s priv;
374	  struct ymodem_ctx_s ctx;
375	  FAR char *devname = NULL;
376	  size_t len;
377	  int ret;
378	
379	  struct option options[] =
380	    {
381	      {"buffersize", 1, NULL, 'b'},
382	      {"skip_prefix", 1, NULL, 'p'},
383	      {"skip_suffix", 1, NULL, 's'},
384	      {"prepend_prefix", 1, NULL, 'e'},
385	      {"append_suffix", 1, NULL, 'a'},
386	      {"threshold", 1, NULL, 't'},
387	      {"interval", 1, NULL, 'i'},
388	      {"retry", 1, NULL, 'r'},
389	    };
390	
391	  memset(&priv, 0, sizeof(priv));
392	  priv.prepend_prefix = "";
393	  priv.append_suffix  = "";
394	  memset(&ctx, 0, sizeof(ctx));
395	  ctx.interval = 15;
396	  ctx.retry = 100;
397	  while ((ret = getopt_long(argc, argv, "b:d:f:hk:p:s:t:i:r:e:a:",
398	                            options, NULL)) != ERROR)
399	    {
400	      switch (ret)
401	        {
402	          case 'b':
403	            priv.buffersize = atoi(optarg) * 1024;
404	            break;
405	          case 'd':
406	            devname = optarg;
407	            break;
408	          case 'f':
409	            priv.foldname = optarg;
410	            len = strlen(priv.foldname);
411	            if (len > 0 && priv.foldname[len - 1] == '/')
412	              {
413	                priv.foldname[len - 1] = '\0';
414	              }
415	
416	            break;
417	          case 'h':
418	            show_usage(argv[0]);
419	            break;
420	          case 'k':
421	            ctx.custom_size = atoi(optarg) * 1024;
422	            break;
423	          case 'p':
424	            priv.skip_prefix = optarg;
425	            break;
426	          case 's':
427	            priv.skip_suffix = optarg;
428	            break;
429	          case 'e':
430	            priv.prepend_prefix = optarg;
431	            break;
432	          case 'a':
433	            priv.append_suffix = optarg;
434	            break;
435	          case 't':
436	            priv.threshold = atoi(optarg) * 1024;
437	            break;
438	          case 'i':
439	            ctx.interval = atoi(optarg);
440	            break;
441	          case 'r':
442	            ctx.retry = atoi(optarg);
443	            break;
444	
445	          case '?':
446	          default:
447	            show_usage(argv[0]);
448	            break;
449	        }
450	    }
451	
452	  if (priv.buffersize && (priv.threshold > priv.buffersize ||
453	                          ctx.custom_size > priv.buffersize))
454	    {
455	      show_usage(argv[0]);
456	    }
457	
458	  if (priv.buffersize)
459	    {
460	      ret = async_init(&priv);
461	      if (ret < 0)
462	        {
463	          return ret;
464	        }
465	    }
466	
467	  ctx.packet_handler = handler;
468	  ctx.priv = &priv;
469	  if (devname)
470	    {
471	      ctx.recvfd = open(devname, O_RDWR);
472	      if (ctx.recvfd < 0)
473	        {
474	          fprintf(stderr, "ERROR: can't open %s\n", devname);
475	          goto out;
476	        }
477	
478	        ctx.sendfd = ctx.recvfd;
479	    }
480	  else
481	    {
482	      ctx.recvfd = STDIN_FILENO;
483	      ctx.sendfd = STDOUT_FILENO;
484	    }
485	
486	  ret = ymodem_recv(&ctx);
487	  if (ctx.recvfd > 0)
488	    {
489	      close(ctx.recvfd);
490	    }
491	
492	out:
493	  if (priv.buffersize)
494	    {
495	      async_uninit(&priv);
496	    }
497	
498	  if (priv.fd > 0)
499	    {
500	      close(priv.fd);
501	    }
502	
503	  return ret;
504	}
