470	  ctx->header[0] = EOT;
471	  ret = ymodem_send_buffer(ctx, ctx->header, 1);
472	  if (ret < 0)
473	    {
474	      ymodem_debug("send EOT error\n");
475	      return ret;
476	    }
477	
478	  ret = ymodem_recv_cmd(ctx, ACK);
479	  if (ret == -EAGAIN)
480	    {
481	      ymodem_debug("send EOT recv NAK, need send again\n");
482	      goto send_eot;
483	    }
484	
485	  if (ret < 0)
486	    {
