507	  ctx->header[0] = SOH;
508	  ctx->header[1] = 0x00;
509	  ctx->header[2] = 0xff;
510	  ctx->packet_type = YMODEM_DATA_PACKET;
511	  ctx->packet_size = YMODEM_PACKET_SIZE;
512	  memset(ctx->data, 0, YMODEM_PACKET_SIZE);
513	  crc = crc16(ctx->data, ctx->packet_size);
