187	static int ymodem_recv_file(FAR struct ymodem_ctx_s *ctx)
188	{
189	  FAR char *str = NULL;
190	  uint32_t total_seq = 0;
191	  int retries = 0;
192	  int ret;
193	
194	  ctx->header[0] = CRC;
195	recv_packet:
196	  ymodem_send_buffer(ctx, ctx->header, 1);
197	  ret = ymodem_recv_packet(ctx);
198	  if (ret == -ECANCELED)
199	    {
200	      ymodem_debug("recv_file: canceled by sender\n");
201	      goto cancel;
202	    }
203	  else if (ret == -EAGAIN)
204	    {
205	      ctx->header[0] = ACK;
206	      ymodem_send_buffer(ctx, ctx->header, 1);
207	      ymodem_debug("recv_file: finished one file transfer\n");
208	      ctx->header[0] = CRC;
209	      total_seq = 0;
210	      goto recv_packet;
211	    }
212	  else if (ret < 0)
213	    {
214	      /* other errors, like ETIMEDOUT, EILSEQ, EBADMSG... */
215	
216	      tcflush(ctx->recvfd, TCIOFLUSH);
217	      if (++retries > ctx->retry)
218	        {
219	          ymodem_debug("recv_file: too many errors, cancel!!\n");
220	          goto cancel;
221	        }
222	
223	      /* Use str to mask transfer start */
224	
225	      ctx->header[0] = str ? NAK : CRC;
226	      goto recv_packet;
227	    }
228	
229	  if ((total_seq & 0xff) - 1 == ctx->header[1])
230	    {
231	      ymodem_debug("recv_file: Received the previous packet that has"
232	                   "been received, continue %" PRIu32 " %u\n", total_seq,
233	                   ctx->header[1]);
234	
235	      ctx->header[0] = ACK;
236	      goto recv_packet;
237	    }
238	  else if ((total_seq & 0xff) != ctx->header[1])
239	    {
240	      ymodem_debug("recv_file: total seq error:%" PRIu32 " %u\n", total_seq,
241	                   ctx->header[1]);
242	      ctx->header[0] = CRC;
243	      goto recv_packet;
244	    }
245	
246	  /* File name packet */
247	
248	  if (total_seq == 0)
249	    {
250	      /* Filename packet is empty, end session */
251	
252	      if (ctx->data[0] == '\0')
253	        {
254	          /* Last file done, so the session also finished */
255	
256	          ymodem_debug("recv_file: session finished\n");
257	          ctx->header[0] = ACK;
258	          ymodem_send_buffer(ctx, ctx->header, 1);
259	          return 0;
260	        }
261	
262	      str = (FAR char *)ctx->data;
263	      ctx->packet_type = YMODEM_FILENAME_PACKET;
264	      strlcpy(ctx->file_name, str, PATH_MAX);
265	      str += strlen(str) + 1;
266	      ctx->file_length = atoi(str);
267	      ymodem_debug("recv_file: new file %s(%zu) start\n", ctx->file_name,
268	                   ctx->file_length);
269	      ret = ctx->packet_handler(ctx);
270	      if (ret < 0)
271	        {
272	          ymodem_debug("recv_file: handler err for file name packet:"
273	                       " ret=%d\n", ret);
274	          goto cancel;
275	        }
276	
277	      ctx->header[0] = ACK;
278	      ymodem_send_buffer(ctx, ctx->header, 1);
279	      ctx->header[0] = CRC;
280	      total_seq++;
281	      goto recv_packet;
282	    }
283	
284	  /* data packet */
285	
286	  ctx->packet_type = YMODEM_DATA_PACKET;
287	  ret = ctx->packet_handler(ctx);
288	  if (ret < 0)
289	    {
290	      ymodem_debug("recv_file: handler err for data packet: ret=%d\n", ret);
291	      goto cancel;
292	    }
293	
294	  ctx->header[0] = ACK;
295	  total_seq++;
296	  ymodem_debug("recv_file: recv data success\n");
297	  retries = 0;
298	  goto recv_packet;
299	
300	cancel:
301	  ctx->header[0] = CAN;
302	  ymodem_send_buffer(ctx, ctx->header, 1);
303	  ymodem_send_buffer(ctx, ctx->header, 1);
304	  ymodem_debug("recv_file: cancel command sent to sender\n");
305	  return ret;
306	}
