115	static int ymodem_recv_packet(FAR struct ymodem_ctx_s *ctx)
116	{
117	  uint16_t recv_crc;
118	  uint16_t cal_crc;
119	  int ret;
120	
121	  ret = ymodem_recv_buffer(ctx, ctx->header, 1);
122	  if (ret < 0)
123	    {
124	      return ret;
125	    }
126	
127	  switch (ctx->header[0])
128	    {
129	      case SOH:
130	        ctx->packet_size = YMODEM_PACKET_SIZE;
131	        break;
132	      case STX:
133	        ctx->packet_size = YMODEM_PACKET_1K_SIZE;
134	        break;
135	      case STC:
136	        ctx->packet_size = ctx->custom_size;
137	        break;
138	      case EOT:
139	        return -EAGAIN;
140	      case CAN:
141	        ret = ymodem_recv_buffer(ctx, ctx->header, 1);
142	        if (ret < 0)
143	          {
144	            return ret;
145	          }
146	        else if (ctx->header[0] == CAN)
147	          {
148	            return -ECANCELED;
149	          }
150	
151	      default:
152	          ymodem_debug("recv_packet: EBADMSG: header[0]=0x%x\n",
153	                       ctx->header[0]);
154	          return -EBADMSG;
155	    }
156	
157	  ret = ymodem_recv_buffer(ctx, &ctx->header[1],
158	                           2 + ctx->packet_size + 2);
159	  if (ret < 0)
160	    {
161	      ymodem_debug("recv_packet: err=%d\n", ret);
162	      return ret;
163	    }
164	
165	  if ((ctx->header[1] + ctx->header[2]) != 0xff)
166	    {
167	      ymodem_debug("recv_packet: EILSEQ seq[]=%d %d\n",
168	                   ctx->header[1], ctx->header[2]);
169	      return -EILSEQ;
170	    }
171	
172	  recv_crc = (ctx->data[ctx->packet_size] << 8) +
173	              ctx->data[ctx->packet_size + 1];
174	  cal_crc = crc16(ctx->data, ctx->packet_size);
175	  if (cal_crc != recv_crc)
176	    {
177	      ymodem_debug("recv_packet: EBADMSG rcev:cal=0x%x 0x%x\n",
178	                   recv_crc, cal_crc);
179	      return -EBADMSG;
180	    }
181	
182	  ymodem_debug("recv_packet:OK: size=%d, seq=%d\n",
183	               ctx->packet_size, ctx->header[1]);
184	  return 0;
185	}
