67	static int ymodem_recv_buffer(FAR struct ymodem_ctx_s *ctx, FAR uint8_t *buf,
68	                              size_t size)
69	{
70	  size_t i = 0;
71	
72	  ymodem_debug("recv buffer data, read size is %zu\n", size);
73	  while (i < size)
74	    {
75	      ssize_t ret = read(ctx->recvfd, buf + i, size - i);
76	      if (ret >= 0)
77	        {
78	          ymodem_debug("recv buffer data, size %zd\n", ret);
79	          i += ret;
80	        }
81	      else
82	        {
83	          ymodem_debug("recv buffer error, ret %d\n", -errno);
84	          return -errno;
85	        }
86	    }
87	
88	  return 0;
89	}
