91	static int ymodem_send_buffer(FAR struct ymodem_ctx_s *ctx,
92	                              FAR const uint8_t *buf, size_t size)
93	{
94	  size_t i = 0;
95	
96	  ymodem_debug("send buffer data, write size is %zu\n", size);
97	  while (i < size)
98	    {
99	      ssize_t ret = write(ctx->sendfd, buf, size);
100	      if (ret >= 0)
101	        {
102	          ymodem_debug("send buffer data, size %zd\n", ret);
103	          i += ret;
104	        }
105	      else
106	        {
107	          ymodem_debug("send buffer error, ret %d\n", -errno);
108	          return -errno;
109	        }
110	    }
111	
112	  return 0;
113	}
